/** A link to a source, or just its title when the address isn't a web page. */
function sourceLink(address: string, title: string): HTMLElement {
  let url: URL | null = null;
  try {
    url = new URL(address);
  } catch {
    // Not an address; show the title alone.
  }
  if (!url || (url.protocol !== "https:" && url.protocol !== "http:"))
    return element("span", title);
  const link = element("a", title);
  link.href = url.href;
  link.target = "_blank";
  link.rel = "noopener noreferrer";
});

test("no source, no verdict", () => {
  const fromMemory = {
    verdict: "contradicted" as const,
    explanation: "From what I remember, this is false.",
    sources: [],
  };
  assert.equal(sourcedOnly(fromMemory).verdict, "unverified");
  const sourced = {
    ...fromMemory,
    sources: [{ url: "https://a.org", title: "A", says: "No." }],
  };
  assert.equal(sourcedOnly(sourced), sourced);
});

